//이 파일은 EnemyData.h 에 있던 배열 정의를 옮겨 담은 것이다.
//
//헤더에 const로 정의하면 내부 링크라, Data.h를 포함하는 .cpp마다
//같은 데이터가 한 벌씩 복제된다. 정의는 여기 한 곳에만 두고
//헤더에는 extern 선언만 남긴다.
//
//tools/content/split_data.py 가 갈랐다.

